<template>
  <div class="form-builder container">
    <div class="row">
      <div class="col-md-3">
        <div class="controls">
          <div class="control-item">
            <button @click="addField('text')" class="btn btn-primary btn-block">فیلد متن</button>
          </div>
          <div class="control-item">
            <button @click="addField('textarea')" class="btn btn-primary btn-block">فیلد متن طولانی</button>
          </div>
          <div class="control-item">
            <button @click="addField('button')" class="btn btn-primary btn-block">دکمه</button>
          </div>
          <div class="control-item">
            <button @click="addField('checkbox')" class="btn btn-primary btn-block">چک باکس</button>
          </div>
          <div class="control-item">
            <button @click="addField('radio')" class="btn btn-primary btn-block">رادیو باتن</button>
          </div>
        </div>
      </div>
      <div class="col-md-6">
        <VueDraggableNext v-model="fields" @end="updateForm" handle=".field">
          <template v-for="(field, index) in fields" :key="index">
            <div
              :class="['field-container', `col-${field.colSpan}`, { selected: selectedField === index }]"
              @click="selectField(index)"
            >
              <div class="field">
                <label>{{ field.label }}</label>
                <input v-if="field.type === 'text'" type="text" :placeholder="field.label" :name="field.name" class="form-control" />
                <textarea v-if="field.type === 'textarea'" :placeholder="field.label" :name="field.name" class="form-control"></textarea>
                <button v-if="field.type === 'button'" class="btn btn-secondary col-12" :name="field.name" >{{ field.label }}</button>
                <input v-if="field.type === 'checkbox'" type="checkbox" class="form-check-input" :name="field.name" :value="field.label" /> 
                <input v-if="field.type === 'radio'" type="radio" class="form-check-input" :name="field.name" :value="field.label" />
              </div>
            </div>
          </template>
        </VueDraggableNext>
      </div>
      <div class="col-md-3">
        <div v-if="selectedField !== null" class="field-settings">
          <h2>ویژگی ها</h2>
          <label>عنوان:</label>
          <input v-model="fields[selectedField].label" class="form-control" />
          <label>نام فیلد:</label>
          <input v-model="fields[selectedField].name" class="form-control" />
          <label>عرض:</label>
          <select v-model="fields[selectedField].colSpan" class="form-select">
            <option v-for="i in 12" :key="i" :value="i">{{ i }}</option>
          </select>
          <button @click="removeField" class="btn btn-danger">حذف فیلد</button>
        </div>
      </div>
    </div>
    <div class="form-json mt-4">
      <h2>Form JSON</h2>
      <pre>{{ JSON.stringify(fields, null, 2) }}</pre>
    </div>
  </div>
</template>

<script>
import { defineComponent, ref, onMounted, onUnmounted } from 'vue';
import { VueDraggableNext } from 'vue-draggable-next';

export default defineComponent({
  components: {
    VueDraggableNext,
  },
  setup() {
    const fields = ref([]);
    const selectedField = ref(null);

    const addField = (type) => {
      const newField = {
        type,
        label: 'عنوان',
        name,
        colSpan: 12, // Initial width set to full width
      };
      fields.value.push(newField);
    };

    const removeField = () => {
      if (selectedField.value !== null) {
        fields.value.splice(selectedField.value, 1);
        selectedField.value = null;
      }
    };

    const selectField = (index) => {
      selectedField.value = index;
    };

    const handleKeydown = (event) => {
      if (event.key === 'Delete') {
        removeField();
      }
    };

    const updateForm = () => {
      console.log('Form updated:', fields.value);
    };

    onMounted(() => {
      window.addEventListener('keydown', handleKeydown);
    });

    onUnmounted(() => {
      window.removeEventListener('keydown', handleKeydown);
    });

    return {
      fields,
      addField,
      removeField,
      selectField,
      selectedField,
      updateForm,
    };
  },
});
</script>

<style>
.form-builder {
  padding: 20px;
  max-width: 1200px;
  margin: auto;
}

.field-container {
  display: flex;
  align-items: center;
  margin-bottom: 10px;
}

.field {
  border: 1px solid #ddd;
  padding: 10px;
  background: #f9f9f9;
  cursor: move;
  flex-grow: 1;
}

.field.selected {
  border-color: #007bff;
  background-color: #e0f7ff; /* Different background color for selected field */
}

.controls {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-bottom: 10px;
}

.control-item {
  margin-bottom: 10px;
}

.btn-block {
  width: 100%;
}

.field-settings {
  background: #f1f1f1;
  padding: 10px;
  border: 1px solid #ddd;
  margin-bottom: 20px;
}

.form-json {
  background: #f1f1f1;
  padding: 10px;
  border: 1px solid #ddd;
}
</style>
